/**
 * V-04: federal income tax and payroll tax against PSL Tax-Calculator fixtures (within $1).
 * Fixtures are generated by tests/validation/taxcalc/generate_fixtures.py (test-time oracle only).
 */
import { readFileSync } from 'node:fs';
import { loadEngineData } from '@fisim/data/src/node';
import type { FilingStatus } from '@fisim/data';
import { emptyFederalInput, federalTax } from '@fisim/engine';
import { describe, expect, it } from 'vitest';

interface Household {
  id: string;
  description: string;
  input: {
    filingStatus: FilingStatus;
    ages: number[];
    childrenUnder17: number;
    wages: number[];
    selfEmployment: number[];
    taxableInterest: number;
    ordinaryDividends: number;
    qualifiedDividends: number;
    longTermGains: number;
    shortTermGains: number;
    pensionsTaxable: number;
    iraDistributions: number;
    socialSecurity: number;
    itemized: {
      stateLocalIncomeTax: number;
      realEstateTax: number;
      mortgageInterest: number;
      charity: number;
    };
  };
  expected: Record<string, number>;
}

const data = loadEngineData();
const file = JSON.parse(readFileSync(new URL('./fixtures/taxcalc-2026.json', import.meta.url), 'utf8')) as {
  meta: { taxcalcVersion: string };
  households: Household[];
};

export function runHousehold(h: Household): ReturnType<typeof federalTax> {
  const x = emptyFederalInput();
  const i = h.input;
  x.status = i.filingStatus;
  x.ages = i.ages;
  x.childrenUnder17 = i.childrenUnder17;
  x.wages = [i.wages[0] ?? 0, i.wages[1] ?? 0];
  x.ficaWages = [i.wages[0] ?? 0, i.wages[1] ?? 0];
  x.selfEmployment = [i.selfEmployment[0] ?? 0, i.selfEmployment[1] ?? 0];
  x.interest = i.taxableInterest;
  x.ordinaryDividends = i.ordinaryDividends - i.qualifiedDividends;
  x.qualifiedDividends = i.qualifiedDividends;
  x.longTermGains = i.longTermGains;
  x.shortTermGains = i.shortTermGains;
  x.pensions = i.pensionsTaxable;
  x.iraDistributions = i.iraDistributions;
  x.socialSecurity = i.socialSecurity;
  x.itemized = {
    stateLocalTax: i.itemized.stateLocalIncomeTax + i.itemized.realEstateTax,
    mortgageInterest: i.itemized.mortgageInterest,
    charity: i.itemized.charity,
  };
  let p = data.federal[2026];
  if (i.filingStatus === 'mfs' && i.socialSecurity > 0) {
    // Known oracle difference: Tax-Calculator treats married-filing-separately filers as living apart (single thresholds for
    // taxing Social Security). The dataset encodes the lived-together rule ($0). Use the oracle's convention for these households.
    p = {
      ...p,
      socialSecurityTaxation: {
        base: { ...p.socialSecurityTaxation.base, mfs: p.socialSecurityTaxation.base.single },
        adjusted: { ...p.socialSecurityTaxation.adjusted, mfs: p.socialSecurityTaxation.adjusted.single },
      },
    };
  }
  return federalTax(p, 1, x);
}

describe(`V-04 Tax-Calculator ${file.meta.taxcalcVersion}, tax year 2026 (${file.households.length} households)`, () => {
  it('has at least 200 fixture households', () => expect(file.households.length).toBeGreaterThanOrEqual(200));
  const bad: string[] = [];
  for (const h of file.households) {
    const r = runHousehold(h);
    const e = h.expected;
    const dIncome = r.incomeTax - (e.incomeTax + e.eitc);
    const dPayroll =
      r.ficaEmployee +
      r.selfEmploymentTax +
      r.additionalMedicareTax -
      (e.employeePayrollTax + e.selfEmploymentTax + e.additionalMedicareTax);
    if (Math.abs(dIncome) > 1 || Math.abs(dPayroll) > 1) {
      bad.push(
        `${h.id} [${h.description}] income Δ${dIncome.toFixed(2)} payroll Δ${dPayroll.toFixed(2)} | agi ${r.agi.toFixed(0)}/${e.agi} ti ${r.taxableIncome.toFixed(0)}/${e.taxableIncome} ded ${(r.deduction - r.seniorDeduction).toFixed(0)}/${e.standardOrItemizedDeduction} sen ${r.seniorDeduction.toFixed(0)}/${e.seniorDeduction} qbi ${r.qbiDeduction.toFixed(0)}/${e.qbiDeduction} reg ${(r.ordinaryTax + r.capitalGainsTax).toFixed(0)}/${e.regularTaxBeforeCredits} amt ${r.amt.toFixed(0)}/${e.amt} niit ${r.niit.toFixed(0)}/${e.niit} ctc ${r.childTaxCredit.toFixed(0)}/${e.childTaxCreditNonrefundable} actc ${r.additionalChildTaxCredit.toFixed(0)}/${e.additionalChildTaxCredit} ss ${r.taxableSocialSecurity.toFixed(0)}/${e.taxableSocialSecurity}`,
      );
    }
  }
  it('federal income tax and payroll tax match within $1 for every household', () => {
    expect(bad, `${bad.length} mismatches:\n${bad.join('\n')}`).toEqual([]);
  });
});
